-- =====================================================================
-- Migration 0004 · 系统配置幂等种子（角色 / 场景 / 剧本节点 / 字典 / 表单）
-- 生成来源：node/src/seed_data.js + node/src/scenario_baseline.js (HEAD)
-- 安全约定：
--   * 角色：INSERT ... ON DUPLICATE KEY UPDATE（系统定义必须存在，权限完整）
--   * 场景/剧本节点：INSERT IGNORE（只补缺失，绝不覆盖用户已编辑内容）
--   * 字典/表单：upsert（流程字典必须完整）
--   * 本文件不含任何 DELETE / TRUNCATE / DROP
-- =====================================================================
SET NAMES utf8mb4;

-- ---- 12 个系统角色（平台管理员必须存在） ----
ON DUPLICATE KEY UPDATE name=VALUES(name), short=VALUES(short), icon=VALUES(icon), color=VALUES(color), descr=VALUES(descr), nav=VALUES(nav), `external`=VALUES(`external`), status='启用', seq=VALUES(seq);

-- ---- 8 个标准演练场景 ----
ON DUPLICATE KEY UPDATE nodes=GREATEST(COALESCE(nodes,0),VALUES(nodes));

-- ---- 剧本节点（8 场景：主流 + 混淆；INSERT IGNORE 保护用户编辑） ----

-- ---- 流程字典（19 键） ----
;


-- ---- 8 类表单模板 ----
ON DUPLICATE KEY UPDATE name=VALUES(name), fields=VALUES(fields);

