  ('role_mvnaewi63am','数据安全管理员','门诊部主任','user','#4f7cff','系统发生故障后，负责核查数据备份情况，并配合系统工程师完成系统恢复工作。',CONVERT(0x5b22776f726b62656e6368222c22636f6c6c6162225d USING utf8mb4),0,'启用',3),
