INSERT INTO scenarios (id,name,type,level,status,version,updated,nodes,descr,alert) VALUES
  ('S01','勒索病毒攻击演练','','重大','启用','v1.0','2026-11-05',18,'内网终端中招、文件加密、勒索提示，评估HIS服务器感染风险，推演断网隔离、备份恢复与上报流程。','T+0 监控平台推送紧急告警：HIS 门诊工作站与共享文件服务器出现大量文件被加密（扩展名变为 .locked），桌面弹出勒索信；已有 3 台终端无法打开业务系统，疑似勒索病毒正在院内网横向扩散。'),
  ('S02','内网横向渗透/账号泄露','','较大','启用','v1.0','2026-11-05',13,'弱口令入侵后横向移动，电子病历数据遭非法访问，推演账号排查、终端隔离与取证。','T+0 监测发现电子病历系统存在异常账号登录与批量查询行为：同一账号在 10 分钟内从 4 台不同终端访问病历，疑似弱口令被利用并横向渗透，部分病历数据可能已被非法访问。'),
  ('S03','DDoS攻击致门诊收费卡顿','','较大','启用','v1.0','2026-11-05',13,'门诊收费系统遭流量攻击卡顿，推演流量清洗协调、窗口纸质兜底与业务恢复确认。','T+0 门诊收费系统出现大面积卡顿并间歇性超时，外网出口流量异常激增（峰值约为日常的 30 倍），收费窗口排队积压，疑似遭受 DDoS 流量攻击。'),
  ('S04','钓鱼邮件跳板入侵','','一般','启用','v1.0','2026-11-05',13,'信息科人员点击木马邮件，攻击者获取跳板，推演邮件排查、全员通报与账号重置。','T+0 信息科多名人员收到伪装为“医保结算通知”的邮件并点击附件，随后终端出现可疑外联行为与异常进程，疑似钓鱼木马已在办公终端取得跳板权限。'),
  ('S05','核心存储故障系统宕机','','重大','启用','v1.0','2026-11-05',14,'核心存储/数据库故障致HIS、EMR整体宕机，推演灾备切换、兜底流程与恢复验证。','T+0 核心存储阵列发出硬件告警，HIS、EMR 等业务系统整体无法访问，数据库连接持续失败，门诊挂号、收费与住院医嘱业务中断，需立即启动应急与业务兜底。'),
  ('S06','患者隐私数据泄露（舆情发酵）','','重大','启用','v1.0','2026-11-05',13,'虚拟患者数据在外部论坛售卖引发舆情，推演上报、口径审批、舆情管控与报案取证。','T+0 监测发现虚拟患者数据在外部论坛被公开售卖，样本包含姓名、就诊科室与就诊记录；相关截图已在社交媒体传播，存在舆情快速发酵与监管问责风险。'),
  ('S07','外网边界防火墙被突破','','较大','启用','v1.0','2026-11-05',13,'边界设备被突破、多业务系统并发告警，推演边界收敛、策略调整与全网排查。','T+0 外网边界防火墙检测到异常穿透与策略篡改行为，多个业务系统同时出现异常访问告警，疑似边界设备已被突破并建立外联通道，需立即收敛边界并开展全网排查。'),
  ('S08','恶意代码批量感染办公网','','一般','启用','v1.0','2026-11-05',14,'办公网终端批量感染恶意代码，业务网暂未波及，推演批量断网、样本摘要提取与查杀。','T+0 办公网多台终端批量弹出异常进程提示并生成可疑文件，终端资源占用异常升高；业务网暂未发现波及，疑似恶意代码在办公网批量感染。')
